import { cn } from '@gntik-ai/ui';
import type { Ref } from 'react';
import { useChatI18n } from '../utils/i18n';
import { typingIndicatorStyles as s } from './typingIndicator.variants';

export interface TypingIndicatorProps {
  /** Who is typing; used in the accessible text ("Assistant is typing"). */
  author?: string;
  /** Show the text next to the dots instead of keeping it screen-reader only. */
  showLabel?: boolean;
  /** Overrides the text entirely. */
  label?: string;
  size?: 'sm' | 'md';
  /**
   * Announce the text through its own polite status region. Off by default: in a thread,
   * ChatAnnouncer already announces "is responding" once.
   */
  announce?: boolean;
  className?: string;
  ref?: Ref<HTMLSpanElement>;
}

/**
 * Three dots that pulse while a reply is being written. The dots are decorative; the text
 * ("Assistant is typing") is always in the accessibility tree. Under reduced motion the dots
 * hold still.
 */
export function TypingIndicator({ author, showLabel = false, label, size = 'md', announce = false, className, ref }: TypingIndicatorProps) {
  const { t, tc } = useChatI18n();
  const text = label ?? tc('chat.typing', { author: author ?? t('chat.assistant') });
  const sz = s.size[size];
  return (
    <span
      ref={ref}
      data-slot="typing-indicator"
      role={announce ? 'status' : undefined}
      className={cn(s.root, className)}
    >
      <span aria-hidden className={cn(s.dots, sz.dots)}>
        <span className={cn(s.dot, sz.dot)} />
        <span className={cn(s.dot, sz.dot, '[animation-delay:150ms]')} />
        <span className={cn(s.dot, sz.dot, '[animation-delay:300ms]')} />
      </span>
      <span className={showLabel ? s.label : 'sr-only'}>{text}</span>
    </span>
  );
}

export { TypingIndicator, type TypingIndicatorProps } from './TypingIndicator';
export { typingIndicatorStyles, streamingCaret } from './typingIndicator.variants';
export { doc as typingIndicatorDoc } from './TypingIndicator.doc';

/** Slot classes for TypingIndicator. Dots pulse in sequence; static under reduced motion. */
export const typingIndicatorStyles = {
  root: 'inline-flex items-center gap-2 text-muted-foreground',
  dots: 'inline-flex h-6 items-center gap-1',
  dot: 'size-1.5 rounded-full bg-muted-foreground animate-pulse motion-reduce:animate-none',
  label: 'text-[12.5px]',
  size: {
    sm: { dots: 'h-4 gap-0.5', dot: 'size-1' },
    md: { dots: '', dot: '' },
  },
} as const;

/** Thin blinking caret after streamed plain text (static under reduced motion). */
export const streamingCaret =
  'ms-0.5 inline-block h-[1.05em] w-[2px] translate-y-[2px] bg-primary animate-pulse motion-reduce:animate-none';

import { interpolate, useI18n, type MessageKey, type MessageVars } from '@gntik-ai/ui';

/**
 * English fallbacks for the chat keys added after the first `@gntik-ai/ui` release. The
 * strings live in the ui catalogs (en + es); these keep the pack readable when it runs
 * against an older `@gntik-ai/ui` whose catalog does not have them yet.
 */
const FALLBACK = {
  'chat.typing': '{author} is typing',
  'chat.feedback': 'Response feedback',
  'chat.feedbackTitle': 'What went wrong?',
  'chat.feedbackReason': 'Reason',
  'chat.feedbackComment': 'Comment (optional)',
  'chat.feedbackPlaceholder': 'Tell us more…',
  'chat.feedbackSubmit': 'Send feedback',
  'chat.feedbackThanks': 'Thanks for your feedback',
  'chat.feedbackCleared': 'Feedback removed',
  'chat.reasonInaccurate': 'Inaccurate',
  'chat.reasonUnhelpful': 'Not helpful',
  'chat.reasonIncomplete': 'Incomplete',
  'chat.reasonUnsafe': 'Harmful or unsafe',
  'chat.reasonOther': 'Other',
  'chat.regenerate': 'Regenerate',
  'chat.uploading': 'Uploading {name}',
  'chat.uploadFailed': 'Upload failed',
  'chat.retryUpload': 'Retry uploading {name}',
  'chat.dropFiles': 'Drop files to attach',
  'chat.fileTooLarge': '{name} is larger than {max}',
  'chat.fileTypeNotAllowed': '{name} is not an allowed file type',
  'chat.tooManyFiles': 'You can attach up to {max} files',
  'chat.model': 'Model',
  'chat.selectModel': 'Select a model',
  'chat.capabilityVision': 'Vision',
  'chat.capabilityTools': 'Tools',
  'chat.capabilityReasoning': 'Reasoning',
  'chat.capabilityFiles': 'Files',
  'chat.capabilityWeb': 'Web search',
  'chat.capabilityAudio': 'Audio',
  'chat.contextWindow': '{size} context',
  'chat.unavailable': 'Unavailable',
} as const;

export type ChatMessageKey = keyof typeof FALLBACK;

/** `useI18n()` plus `tc()`, a translator for the newer chat keys with English fallbacks. */
export function useChatI18n() {
  const i18n = useI18n();
  const tc = (key: ChatMessageKey, vars?: MessageVars) => {
    const out = i18n.t(key as MessageKey, vars);
    return out === key ? interpolate(FALLBACK[key], vars, i18n.locale) : out;
  };
  return { ...i18n, tc };
}

import type { ComponentDoc } from '@gntik-ai/ui';

export const doc: ComponentDoc = {
  name: 'TypingIndicator',
  group: 'Feedback',
  status: 'beta',
  description:
    'Three pulsing dots shown while a reply is being written, with the text "Assistant is typing" for screen readers (or visible with `showLabel`). The dots are decorative and hold still under reduced motion. ChatMessage renders it while a streaming turn is still empty.',
  keyboard: [],
  tokens: ['muted-foreground'],
};
